const page = (html, mount = null) => ({ html, mount });
const intro = (title, description, actions = '') => `<div class="page-intro"><div><h3>${escapeHtml(title)}</h3><p>${escapeHtml(description)}</p></div><div class="page-actions">${actions}</div></div>`;
const card = (title, body, actions = '', className = '') => `<section class="card ${className}"><div class="card-title"><h3>${escapeHtml(title)}</h3><div class="row">${actions}</div></div>${body}</section>`;
