const gateName = n => ({ 1: 'گیت ۱: انتخاب ایده', 2: 'گیت ۲: تأیید سناریو و راستی‌آزمایی', 3: 'گیت ۳: تأیید بسته نهایی' }[n] || `گیت ${n}`);
