function registerSvg(svg) { const key = `svg_${Math.random().toString(36).slice(2)}`; svgRegistry.set(key, svg); return key; }
function mediaList(content) { const links = parse(content.media_links_json, []) || []; return links.length ? `<div class="list">${links.map((m, i) => `<div class="list-item row"><span class="badge ${mediaKind(m) === 'video' ? 'purple' : 'info'}">${mediaKind(m) === 'video' ? 'ویدیو' : 'تصویر'} ${faDigits(i + 1)}</span><a href="${escapeHtml(mediaUrl(m))}" target="_blank" rel="noopener" class="truncate">${escapeHtml(mediaUrl(m))}</a></div>`).join('')}</div>` : notice('هنوز لینک رسانه نهایی ثبت نشده است. فایل‌ها به‌صورت پیش‌فرض لینک خارجی هستند.', 'warn'); }
function gateForm(content, gate) {
  if (!gate || gate.status !== 'PENDING') return '';
  const ideas = parse(content.ideation_json, {})?.ideas || [];
  const validation = parse(content.validator_report_json, null);
  return `<form class="card gate-form" data-gate-form data-content-id="${escapeHtml(content.id)}" data-gate-number="${gate.gate_number}">
    <div class="spread"><div><h3>${gateName(gate.gate_number)}</h3><p class="muted small">نسخه ${faDigits(gate.version)} · تصمیم فقط یک‌بار ثبت می‌شود؛ ارسال هم‌زمان «already decided» می‌گیرد.</p></div>${badge('در انتظار مالک', 'warn')}</div>
    ${gate.gate_number === 1 ? `<div class="grid two" style="margin:15px 0">${ideas.map((idea, i) => `<label class="list-item check-label" style="align-items:flex-start"><input type="radio" name="selected_idea_index" value="${i}" ${i === 0 ? 'checked' : ''}><span><strong>${format(idea.format)} · ${escapeHtml(idea.hook || '')}</strong><br><span class="muted small">${escapeHtml(idea.angle || '')} — ${escapeHtml(idea.key_message || '')}</span><br><span class="small">CTA: ${escapeHtml(idea.cta || '')} · تلاش: ${escapeHtml(idea.effort || '')}</span></span></label>`).join('')}</div>` : ''}
    ${gate.gate_number === 2 ? factSummary(parse(content.fact_check_json, {})) : ''}
    ${gate.gate_number === 3 && validation ? `<div class="notice ${validation.ok ? 'ok' : 'danger'}" style="margin:12px 0">${validation.ok ? 'بررسی فنی بدون خطای مسدودکننده است.' : '<strong>خطاهای فنی پیش از تأیید:</strong>'}${(validation.issues || []).map(i => `<div>• ${escapeHtml(i.rule || '')}: ${escapeHtml(i.note || '')}</div>`).join('')}</div>` : ''}
    <label>یادداشت برای درخواست اصلاح (برای تأیید اختیاری)<textarea name="note" placeholder="مثلاً: قلاب کوتاه‌تر شود و منبع ادعای دوم اضافه شود"></textarea></label>
    <div class="form-actions"><button type="button" class="btn danger" data-gate-decision="REJECT">رد محتوا</button><button type="button" class="btn warn" data-gate-decision="REQUEST_CHANGES">درخواست اصلاح و نسخه جدید</button><button type="button" class="btn primary" data-gate-decision="APPROVE">تأیید و ادامه</button></div>
  </form>`;
}
function factSummary(fact) {
  const claims = fact?.claims || [];
  return `<div class="notice ${fact?.overall === 'pass' ? 'ok' : fact?.overall === 'block' ? 'danger' : 'warn'}" style="margin:12px 0"><strong>نتیجه راستی‌آزمایی: ${escapeHtml(fact?.overall || 'ثبت نشده')}</strong><p>${escapeHtml(fact?.notes || '')}</p>${claims.length ? `<div class="table-wrap"><table class="table-compact"><thead><tr><th>ادعا</th><th>حکم</th><th>اعتماد</th><th>پیشنهاد اصلاح</th></tr></thead><tbody>${claims.map(c => `<tr><td>${escapeHtml(c.claim)}</td><td>${badge(c.verdict, c.verdict === 'تأییدشده' ? 'ok' : 'warn')}</td><td>${escapeHtml(c.confidence || '')}</td><td>${escapeHtml(c.fix_suggestion || '')}</td></tr>`).join('')}</tbody></table></div>` : '<p class="small">ادعای قابل راستی‌آزمایی ثبت نشده است.</p>'}</div>`;
}
function bindGateForms(root = document) {
  root.querySelectorAll('[data-gate-form]').forEach(form => {
    if (form.dataset.bound) return; form.dataset.bound = '1';
    form.querySelectorAll('[data-gate-decision]').forEach(button => button.addEventListener('click', async () => {
      const decision = button.dataset.gateDecision;
      const note = form.querySelector('[name="note"]')?.value || '';
      if (decision === 'REQUEST_CHANGES' && !note.trim()) { toast('برای درخواست اصلاح، یادداشت بنویسید', 'error'); form.querySelector('[name="note"]')?.focus(); return; }
      if (decision === 'REJECT' && !window.confirm('محتوا رد شود؟ این تصمیم در لاگ ثبت می‌شود.')) return;
      button.disabled = true;
      try {
        const selected = form.querySelector('[name="selected_idea_index"]:checked')?.value;
        const result = await api(`/api/content/${encodeURIComponent(form.dataset.contentId)}/gates/${form.dataset.gateNumber}`, { method: 'POST', body: { decision, note, selected_idea_index: selected === undefined ? undefined : Number(selected) } });
        toast(result.data?.already_decided ? 'already decided — این گیت قبلاً تصمیم گرفته شده است' : 'تصمیم ثبت شد؛ مراحل بعدی در پس‌زمینه اجرا می‌شوند', 'success');
        closeModal(); await renderRoute(); refreshApprovalCount();
      } catch (error) { showError(error); button.disabled = false; }
    }));
  });
}
