  const html = `${intro('تصمیم‌های مالک', 'هر سه گیت Approve / Request changes / Reject دارند. درخواست اصلاح با یادداشت، نسخه تازه و اجرای دوباره Agent می‌سازد.', '<button class="btn ghost" id="approval-refresh">↻ تازه‌سازی</button>')}${details.length ? `<div class="stack">${details.filter(Boolean).map(({ gate, detail }) => gateForm(detail.content, detail.gates.find(x => x.id === gate.id) || gate)).join('')}</div>` : empty('گیت بازی برای تصمیم وجود ندارد', 'از کانبان تولید یک محتوای جدید بسازید یا وضعیت کارهای پس‌زمینه را بررسی کنید.')}`;
