async function playbookPage() {
  const [p, b] = await Promise.all([api('/api/playbook'), api('/api/brand')]); const playbook = p.data || {}; const brand = b.data || {}; const pillars = parse(playbook.pillars_json, []) || [];
  const color = (key, label) => `<label>${label}<input type="color" name="${key}" value="${escapeHtml(brand[key] || '#0f4c5c')}"></label>`;
  const html = `${intro('پلی‌بوک و Brand Kit', 'هر ویرایش پلی‌بوک نسخه جدید می‌سازد. رنگ‌ها و فونت system stack به طراحان به‌صورت DATA داده می‌شود.', '')}<div class="tabs"><button class="tab active" data-knowledge-tab="playbook">پلی‌بوک نسخه ${faDigits(playbook.version || 1)}</button><button class="tab" data-knowledge-tab="brand">Brand Kit</button><button class="tab" data-knowledge-tab="specs">Platform specs</button></div><div id="knowledge-playbook">${card('ویرایش پلی‌بوک', `<form id="playbook-form" class="stack"><label>عنوان<input name="title" value="${escapeHtml(playbook.title || '')}"></label><label>ستون‌های محتوایی (هر خط یک ستون)<textarea name="pillars" rows="7">${escapeHtml(pillars.join('\n'))}</textarea></label><label>لحن و قواعد زبانی<textarea name="tone_of_voice" rows="5">${escapeHtml(playbook.tone_of_voice || '')}</textarea></label><label>مخاطب<textarea name="audience_desc" rows="3">${escapeHtml(playbook.audience_desc || '')}</textarea></label><label>کلمات/ادعاهای ممنوع (هر خط یک مورد)<textarea name="banned" rows="4">${escapeHtml((parse(playbook.banned_words_json, []) || []).join('\n'))}</textarea></label><label>قواعد زمان‌بندی<textarea name="posting_rules_text" rows="4">${escapeHtml(playbook.posting_rules_text || '')}</textarea></label><label>Markdown کامل<textarea name="raw_markdown" rows="9" dir="ltr">${escapeHtml(playbook.raw_markdown || '')}</textarea></label><label>یادداشت نسخه<input name="note" placeholder="دلیل ویرایش"></label><div class="form-actions"><button class="btn primary" type="submit">ذخیره به‌عنوان نسخه جدید</button></div></form>`)}</div><div id="knowledge-brand" class="hidden">${card('رنگ، فونت و هویت بصری', `<form id="brand-form" class="stack"><div class="form-grid three">${color('primary_color', 'رنگ اصلی')}${color('secondary_color', 'رنگ دوم')}${color('accent_color', 'رنگ تأکید')}${color('bg_light_color', 'پس‌زمینه روشن')}${color('bg_dark_color', 'پس‌زمینه تیره')}${color('text_dark_color', 'متن تیره')}${color('text_light_color', 'متن روشن')}</div><label>Font stack (بدون Google Fonts CDN)<input name="font_family_css" dir="ltr" value="${escapeHtml(brand.font_family_css || '')}"></label><label>لینک لوگو (اختیاری، HTTPS)<input name="logo_url" dir="ltr" value="${escapeHtml(brand.logo_url || '')}"></label><label>متن واترمارک<input name="watermark_text" value="${escapeHtml(brand.watermark_text || '')}"></label><label>حاشیه امن SVG (پیکسل)<input name="safe_margin_px" type="number" min="0" max="300" value="${brand.safe_margin_px || 80}"></label><label>خلاصه لحن<textarea name="tone_summary">${escapeHtml(brand.tone_summary || '')}</textarea></label><div class="form-actions"><button class="btn primary" type="submit">ذخیره Brand Kit</button></div></form>`)}</div><div id="knowledge-specs" class="hidden">${card('مشخصات پلتفرم‌ها و تاریخ راستی‌آزمایی', '<div id="specs-content">در حال بارگذاری…</div>')}</div>`;
  return page(html, async () => {
    $$('[data-knowledge-tab]').forEach(button => button.addEventListener('click', () => { $$('[data-knowledge-tab]').forEach(b => b.classList.toggle('active', b === button)); ['playbook', 'brand', 'specs'].forEach(name => $(`#knowledge-${name}`)?.classList.toggle('hidden', name !== button.dataset.knowledgeTab)); }));
    $('#playbook-form')?.addEventListener('submit', async event => { event.preventDefault(); const data = formData(event.target); try { await api('/api/playbook', { method: 'PUT', body: { title: data.title, pillars: data.pillars.split(/\n+/).map(x => x.trim()).filter(Boolean), tone_of_voice: data.tone_of_voice, audience_desc: data.audience_desc, banned_words: data.banned.split(/\n+/).map(x => x.trim()).filter(Boolean), posting_rules_text: data.posting_rules_text, raw_markdown: data.raw_markdown, note: data.note } }); toast('پلی‌بوک نسخه جدید شد', 'success'); await renderRoute(); } catch (e) { showError(e); } });
    $('#brand-form')?.addEventListener('submit', async event => { event.preventDefault(); const data = formData(event.target); try { await api('/api/brand', { method: 'PUT', body: data }); toast('Brand Kit ذخیره شد', 'success'); } catch (e) { showError(e); } });
    try {
      const specs = await api('/api/platform-specs');
      $('#specs-content').innerHTML = `<div class="notice info">این مقادیر از D1 خوانده و به Agents به‌عنوان DATA داده می‌شوند؛ از حافظه مدل استفاده نمی‌شود. تاریخ آخرین بررسی: ${faDigits('2026-11-04')}</div><div class="stack" style="margin-top:12px">${(specs.data || []).map(s => `<details class="list-item"><summary><strong>${escapeHtml(s.platform)} · ${escapeHtml(s.format)} · ${escapeHtml(s.spec_key)}</strong></summary><p class="small">${escapeHtml(s.summary_fa)}</p><pre class="json-box">${pretty(parse(s.spec_value_json, {}))}</pre><a class="small ltr" href="${escapeHtml(s.source_url)}" target="_blank" rel="noopener">${escapeHtml(s.source_url)}</a><div class="small muted">last_verified: ${faDigits(s.last_verified)}</div></details>`).join('')}</div>`;
    } catch { $('#specs-content').textContent = 'مشخصات پلتفرم در دسترس نیست.'; }
  });
}

async function agentsPage() {
  const r = await api('/api/agents'); const agents = r.data || []; let selected = agents[0]?.id;
  const html = `${intro('تیم مجازی و ویرایش پرامپت', 'پرامپت‌ها از جدول agents در D1 خوانده می‌شوند؛ هیچ پرامپت runtime-only در Worker وجود ندارد. خروجی فقط JSON و بدون ابزار است.', '<button class="btn ghost" id="agents-reload">↻</button>')}${notice('ویرایش پرامپت، version Agent را زیاد می‌کند و cache ورودی‌های جدید را از نسخه قبلی جدا می‌کند. تست اجرا هیچ اقدام خارجی ندارد.', 'info')}<div class="grid two" style="margin-top:16px"><div>${card('۱۲ عضو تیم', `<label>انتخاب Agent<select id="agent-select">${agents.map(a => `<option value="${escapeHtml(a.id)}">${escapeHtml(a.name_fa)} · ${escapeHtml(a.id)}</option>`).join('')}</select></label><div id="agent-list" class="list" style="margin-top:14px">${agents.map(a => `<div class="list-item spread"><div><strong>${escapeHtml(a.name_fa)}</strong><div class="small muted">${escapeHtml(a.role_group)} · نسخه ${faDigits(a.version)}</div></div>${a.enabled ? badge('فعال', 'ok') : badge('غیرفعال', 'warn')}</div>`).join('')}</div>`)}</div><div id="agent-editor"></div></div>`;
  const drawEditor = () => {
    const a = agents.find(x => x.id === selected); if (!a) return;
    $('#agent-editor').innerHTML = card(`ویرایش ${a.name_fa}`, `<form id="agent-form" class="stack"><div class="form-grid"><label>Provider<select name="provider"><option value="default">پیش‌فرض Secrets</option><option value="workers_ai">Workers AI</option><option value="gemini">Gemini</option><option value="openai_compatible">OpenAI-compatible</option></select></label><label>Model<input name="model" dir="ltr" value="${escapeHtml(a.model || '')}" placeholder="پیش‌فرض provider"></label></div><label>Base URL برای OpenAI-compatible (اختیاری)<input name="base_url" dir="ltr" value="${escapeHtml(a.base_url || '')}"></label><div class="form-grid"><label>حداکثر توکن خروجی<input name="max_tokens" type="number" min="256" max="12000" value="${a.max_tokens}"></label><label>سقف توکن روزانه Agent<input name="daily_token_cap" type="number" min="100" value="${a.daily_token_cap}"></label></div><label>System prompt فارسی<textarea name="system_prompt" rows="18" required>${escapeHtml(a.system_prompt)}</textarea></label><label class="check-label"><input type="checkbox" name="enabled" ${a.enabled ? 'checked' : ''}> Agent فعال باشد</label><div class="form-actions"><button type="button" class="btn ghost" id="agent-restore">بازگردانی پرامپت اولیه</button><button type="submit" class="btn primary">ذخیره و افزایش نسخه</button></div></form><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><form id="agent-test-form" class="stack"><h4>تست اجرای JSON</h4><label>متن آزمایشی (به‌عنوان داده غیرقابل اعتماد)<textarea name="text" placeholder="یک مثال برای تست این Agent"></textarea></label><button class="btn subtle" type="submit">اجرای تست بدون side effect</button><div id="agent-test-result"></div></form>`);
    const form = $('#agent-form'); form.provider.value = a.provider || 'default';
    form.addEventListener('submit', async event => { event.preventDefault(); const data = formData(form); data.enabled = form.enabled.checked; try { const result = await api(`/api/agents/${encodeURIComponent(a.id)}`, { method: 'PUT', body: data }); Object.assign(a, result.data); toast('پرامپت ذخیره شد', 'success'); drawEditor(); } catch (e) { showError(e); } });
    $('#agent-restore')?.addEventListener('click', () => { form.system_prompt.value = a.default_system_prompt; toast('پرامپت اولیه در فرم قرار گرفت؛ برای ذخیره تأیید کنید'); });
    $('#agent-test-form')?.addEventListener('submit', async event => { event.preventDefault(); const button = event.target.querySelector('button'); button.disabled = true; $('#agent-test-result').innerHTML = '<p class="muted">در حال اجرا…</p>'; try { const result = await api(`/api/agents/${encodeURIComponent(a.id)}/test`, { method: 'POST', body: { text: event.target.text.value } }); $('#agent-test-result').innerHTML = `<div class="notice ok">تست موفق · Repair: ${result.data.repair_attempted ? '۱ بار' : '۰'} · توکن: ${number(result.data.usage.total_tokens)}</div><pre class="json-box">${pretty(result.data.parsed)}</pre>`; } catch (e) { $('#agent-test-result').innerHTML = `<div class="notice danger">${escapeHtml(errorText(e))}</div>`; } finally { button.disabled = false; } });
  };
  return page(html, () => { drawEditor(); $('#agent-select')?.addEventListener('change', e => { selected = e.target.value; drawEditor(); }); $('#agents-reload')?.addEventListener('click', renderRoute); });
}

async function inboxPage() {
  const r = await api('/api/inbox'); const messages = r.data || [];
  const html = `${intro('صندوق ورودی و پاسخ‌های پیش‌نویس', 'community_admin فقط دسته‌بندی و پیش‌نویس می‌سازد. ارسال خصوصی/عمومی فقط با دکمه تأیید مالک و پس از بررسی پنجره‌های رسمی انجام می‌شود.', '<button class="btn primary" id="inbox-manual">＋ ورود دستی کامنت/DM</button>')}${notice('قواعد کدشده: یک پاسخ خصوصی برای هر کامنت تا ۷ روز؛ دایرکت فقط در پنجره ۲۴ ساعته از آخرین پیام کاربر و پاسخ بعدی فقط پس از پیام تازه او. پیام انبوه یا سرد وجود ندارد. مسیر Human Agent در GUIDE.fa.md توضیح داده شده است.', 'info')}<div class="stack" style="margin-top:16px">${messages.length ? messages.map(m => { const classification = parse(m.classification_json, {}) || {}; const window = m.window || {}; const deadline = Date.now() + Number(window.remaining_seconds || 0) * 1000; const isDm = m.item_type === 'dm'; const allowed = window.allowed; return `<article class="card" data-inbox-card="${escapeHtml(m.id)}"><div class="spread"><div class="row"><div class="avatar">${escapeHtml((m.sender_username || 'ک').slice(0, 1))}</div><div><strong>${escapeHtml(m.sender_username)}</strong><div class="small muted">${isDm ? 'دایرکت' : 'کامنت'} · ${formatJalali(m.received_at)} · ${m.manual_entry ? 'ورودی دستی' : 'webhook'}</div></div></div><div class="row">${m.escalate ? badge('نیازمند بررسی فوری', 'danger') : ''}${m.is_hidden ? badge('پنهان', 'warn') : ''}${statusBadge(m.reply_status)}</div></div><div class="inbox-text" style="margin:14px 0">${escapeHtml(m.text_raw)}</div><div class="grid two"><div><div class="row">${classification.category ? badge(classification.category, 'info') : ''}${classification.sentiment ? badge(classification.sentiment, 'purple') : ''}</div><p class="small muted">${escapeHtml(classification.reason || 'در انتظار دسته‌بندی ادمین')}</p><div class="notice ${allowed ? 'ok' : 'warn'}"><strong>${isDm ? 'پنجره ۲۴ ساعته' : 'پنجره پاسخ خصوصی ۷ روزه'}:</strong> <span class="countdown ${allowed ? '' : 'expired'}" data-countdown="${deadline}">${countdownText(window.remaining_seconds)}</span><br><span class="small">${escapeHtml(window.reason || (allowed ? 'ارسال مجاز است؛ دوباره در لحظه ارسال بررسی می‌شود.' : 'ارسال خودکار مسدود است.'))}</span></div></div><div><label>پیش‌نویس پاسخ (قابل ویرایش)<textarea data-reply-text>${escapeHtml(m.draft_reply || '')}</textarea></label><div class="form-actions"><button class="btn ghost small-btn" data-inbox-redraft="${escapeHtml(m.id)}">ساخت دوباره پیش‌نویس</button>${!isDm ? `<button class="btn subtle small-btn" data-inbox-send="public" data-inbox-id="${escapeHtml(m.id)}">تأیید پاسخ عمومی</button><button class="btn primary small-btn" data-inbox-send="private" data-inbox-id="${escapeHtml(m.id)}" ${allowed ? '' : 'disabled'}>تأیید پاسخ خصوصی</button><button class="btn warn small-btn" data-inbox-hide="${escapeHtml(m.id)}">${m.is_hidden ? 'آشکارسازی' : 'پنهان‌سازی'}</button>` : `<button class="btn primary small-btn" data-inbox-send="dm" data-inbox-id="${escapeHtml(m.id)}" ${allowed ? '' : 'disabled'}>تأیید و ارسال DM</button>`}</div></div></div>${m.sent_reply_text ? `<p class="small text-ok">پاسخ ثبت‌شده: ${escapeHtml(m.sent_reply_text)}</p>` : ''}</article>`; }).join('') : empty('صندوق ورودی خالی است', 'Webhook اینستاگرام یا ورودی دستی، پیام‌ها را اینجا می‌آورد.')}</div>`;
  return page(html, () => {
    $('#inbox-manual')?.addEventListener('click', () => { openModal('ورود دستی کامنت یا دایرکت', `<form id="manual-inbox-form" class="stack"><div class="form-grid"><label>نوع<select name="item_type"><option value="comment">کامنت</option><option value="dm">دایرکت</option></select></label><label>نام کاربر<input name="sender_username" value="ورودی دستی"></label></div><label>متن<textarea name="text_raw" required></textarea></label><label>زمان دریافت (اختیاری؛ برای تست پنجره‌ها)<input name="received_at" type="datetime-local"></label><p class="help">در Manual Mode همان مدل داده و همان قواعد پنجره اعمال می‌شود؛ ارسال واقعی بدون credential انجام نمی‌شود.</p><div class="form-actions"><button type="button" class="btn ghost" data-close-modal>انصراف</button><button class="btn primary" type="submit">ثبت و ساخت پیش‌نویس</button></div></form>`); $('#manual-inbox-form')?.addEventListener('submit', async event => { event.preventDefault(); const data = formData(event.target); if (data.received_at) data.received_at = new Date(data.received_at).toISOString(); try { await api('/api/inbox/manual', { method: 'POST', body: data }); closeModal(); toast('پیام ثبت شد؛ پیش‌نویس در صف است', 'success'); await renderRoute(); } catch (e) { showError(e); } }); });
    $$('[data-inbox-redraft]').forEach(b => b.addEventListener('click', async () => { try { await api(`/api/inbox/${encodeURIComponent(b.dataset.inboxRedraft)}/draft`, { method: 'POST', body: {} }); toast('پیش‌نویس در صف ساخته می‌شود', 'success'); } catch (e) { showError(e); } }));
    $$('[data-inbox-send]').forEach(b => b.addEventListener('click', async () => { const cardEl = b.closest('[data-inbox-card]'); const reply = cardEl.querySelector('[data-reply-text]').value; if (!reply.trim()) { toast('متن پاسخ خالی است', 'error'); return; } if (!confirmExternal('آیا پاسخ تأییدشده ارسال شود؟ قواعد پنجره و rate limit دوباره در Worker بررسی می‌شوند.')) return; b.disabled = true; try { const result = await api(`/api/inbox/${encodeURIComponent(b.dataset.inboxId)}/send`, { method: 'POST', body: { reply_text: reply, reply_type: b.dataset.inboxSend, confirm: true } }); toast(result.data.manual ? 'اعتبارنامه نیست؛ متن برای ارسال دستی آماده شد' : 'پاسخ ارسال و در لاگ ثبت شد', 'success'); await renderRoute(); } catch (e) { showError(e); b.disabled = false; } }));
    $$('[data-inbox-hide]').forEach(b => b.addEventListener('click', async () => { if (!confirmExternal('وضعیت پنهان‌سازی این کامنت تغییر کند؟')) return; try { await api(`/api/inbox/${encodeURIComponent(b.dataset.inboxHide)}/hide`, { method: 'POST', body: { hide: !b.textContent.includes('آشکار'), confirm: true } }); await renderRoute(); } catch (e) { showError(e); } }));
  });
}

async function analyticsPage() {
  const r = await api('/api/analytics'); const d = r.data; const media = (d.metrics || []).filter(m => m.scope === 'media');
  const byDate = {}; for (const m of media) { const key = m.metric_date; byDate[key] = (byDate[key] || 0) + Number(m.views || 0); }
  const chart = Object.entries(byDate).sort(([a], [b]) => a.localeCompare(b)).slice(-12); const max = Math.max(1, ...chart.map(([, v]) => v));
  const html = `${intro('تحلیل، آمار و آزمایش', 'داده‌های Insights به‌عنوان خلاصه به editorial داده می‌شوند؛ زمان‌بندی بدون داده «داده کافی نیست» است و پیشنهادها فرضیه برای آزمایش‌اند.', '<button class="btn primary" id="insights-pull">به‌روزرسانی Insights</button>')}${d.metrics?.length ? '' : notice('داده کافی نیست. پس از انتشار واقعی و اتصال Instagram Insights، نمودارها و جدول بهترین زمان پر می‌شوند؛ هیچ عددی ساخته نمی‌شود.', 'info')}<div class="grid two" style="margin-top:16px"><div>${card('روند بازدید رسانه‌ها', chart.length ? `<div class="chart">${chart.map(([date, value]) => `<div class="chart-bar"><b>${number(value)}</b><i style="height:${Math.max(3, Math.round(value / max * 135))}px"></i><small>${metricDateLabel(date)}</small></div>`).join('')}</div>` : empty('داده‌ای برای نمودار نیست'))}</div><div>${card('خلاصه تعامل', `<div class="grid two"><div class="metric-card"><div class="metric-label">Reach</div><div class="metric-value">${number(media.reduce((n, m) => n + Number(m.reach || 0), 0))}</div></div><div class="metric-card"><div class="metric-label">Interactions</div><div class="metric-value">${number(media.reduce((n, m) => n + Number(m.interactions || 0), 0))}</div></div><div class="metric-card"><div class="metric-label">Saves</div><div class="metric-value">${number(media.reduce((n, m) => n + Number(m.saves || 0), 0))}</div></div><div class="metric-card"><div class="metric-label">Shares</div><div class="metric-value">${number(media.reduce((n, m) => n + Number(m.shares || 0), 0))}</div></div></div>`)}</div></div><div style="margin-top:16px">${card('جدول بهترین زمان و فرمت (فرضیه‌سازی از داده)', d.best_time?.length ? `<div class="table-wrap"><table><thead><tr><th>فرمت</th><th>ساعت تهران</th><th>تعداد پست</th><th>میانگین Views</th><th>میانگین Reach</th><th>میانگین تعامل</th></tr></thead><tbody>${d.best_time.map(x => `<tr><td>${format(x.format)}</td><td>${x.posted_hour_tehran === null ? '—' : faDigits(x.posted_hour_tehran)}</td><td>${number(x.posts)}</td><td>${number(x.avg_views)}</td><td>${number(x.avg_reach)}</td><td>${number(x.avg_interactions)}</td></tr>`).join('')}</tbody></table></div><p class="small muted">این جدول تضمین الگوریتم نیست؛ برای هر فرضیه آزمایش جدید ثبت کنید.</p>` : empty('داده کافی نیست'))}</div><div style="margin-top:16px">${card('آزمایش‌های تحریریه', `<form id="experiment-form" class="form-grid"><label>عنوان<input name="title" required placeholder="مثلاً: قلاب سؤالی در کروسل"></label><label>متغیر<input name="variable" required placeholder="hook / format / hour"></label><label>فرضیه<input name="hypothesis" required placeholder="فرضیه برای آزمایش..."></label><label>متریک<input name="metric_name" value="saves"></label><div class="form-actions" style="grid-column:1/-1"><button class="btn primary" type="submit">ثبت آزمایش</button></div></form><div class="list" style="margin-top:15px">${(d.experiments || []).map(x => `<div class="list-item"><strong>${escapeHtml(x.title)}</strong><div class="small muted">${escapeHtml(x.variable)} · ${escapeHtml(x.metric_name)} · ${escapeHtml(x.status)}</div><p class="small">${escapeHtml(x.hypothesis)}</p></div>`).join('')}</div>`)}</div>`;
  return page(html, () => { $('#insights-pull')?.addEventListener('click', async event => { event.target.disabled = true; try { const result = await api('/api/insights/pull', { method: 'POST', body: {} }); toast(`Insights ${number(result.data.pulled)} رسانه به‌روزرسانی شد`, 'success'); await renderRoute(); } catch (e) { showError(e); } finally { event.target.disabled = false; } }); $('#experiment-form')?.addEventListener('submit', async event => { event.preventDefault(); try { await api('/api/experiments', { method: 'POST', body: formData(event.target) }); toast('آزمایش ثبت شد', 'success'); await renderRoute(); } catch (e) { showError(e); } }); });
}

function manualPackageView(job) {
  const pack = parse(job.manual_package_json, null); if (!pack) return '';
  return `<details class="list-item"><summary>بسته انتشار دستی ${platformName(job.platform)}</summary><p class="small muted">${escapeHtml(pack.fallback_reason || '')}</p><label>کپشن<textarea readonly>${escapeHtml(pack.caption || '')}</textarea></label><div class="form-actions"><button class="btn ghost small-btn" data-copy-package="${escapeHtml(job.id)}">کپی کپشن</button><button class="btn subtle small-btn" data-download-package="${escapeHtml(job.id)}">دانلود JSON بسته</button><button class="btn primary small-btn" data-mark-published="${escapeHtml(job.id)}">ثبت به‌عنوان منتشرشده + URL</button></div><pre class="json-box">${pretty(pack)}</pre></details>`;
}
async function publishPage() {
  const r = await api('/api/publish'); const jobs = r.data || [];
  const html = `${intro('مرکز انتشار', 'زمان‌بندی، idempotency، polling ویدیو، تلاش مجدد و Manual Package برای هر پلتفرم. retry فقط پس از بررسی وضعیت واقعی انجام دهید.', '<button class="btn ghost" data-route-link="integrations">وضعیت اتصال‌ها</button>')}${jobs.length ? `<div class="stack">${jobs.map(j => `<article class="card"><div class="spread"><div><h3>${escapeHtml(j.title)}</h3><p class="small muted">${platformName(j.platform)} · ${format(j.selected_format)} · ${formatJalali(j.scheduled_at_utc)}</p></div><div class="row">${statusBadge(j.status)}${contentButton(j.content_id, 'محتوا')}</div></div>${j.last_error ? `<div class="notice warn" style="margin:12px 0">${escapeHtml(j.last_error)}</div>` : ''}${j.published_url ? `<p class="small"><strong>URL انتشار:</strong> <a href="${escapeHtml(j.published_url)}" target="_blank" rel="noopener">${escapeHtml(j.published_url)}</a></p>` : ''}${j.container_id ? `<p class="small muted">Container ذخیره‌شده برای جلوگیری از ساخت تکراری: <code>${escapeHtml(j.container_id)}</code></p>` : ''}<div class="form-actions"><button class="btn ghost small-btn" data-publish-retry="${escapeHtml(j.id)}" ${j.status === 'PUBLISHED' ? 'disabled' : ''}>تلاش مجدد</button>${j.status === 'MANUAL_READY' ? `<button class="btn primary small-btn" data-mark-published="${escapeHtml(j.id)}">ثبت انتشار دستی</button>` : ''}</div>${manualPackageView(j)}</article>`).join('')}</div>` : empty('مسیر انتشاری وجود ندارد', 'پس از تأیید گیت ۳ و ساخت تقویم، کارهای هر پلتفرم اینجا ظاهر می‌شوند.')}`;
  const mark = id => { const job = jobs.find(j => j.id === id); openModal('ثبت انتشار دستی', `<form id="mark-published-form" class="stack"><p class="muted small">فقط پس از اینکه پست را واقعاً در پلتفرم دیدید، URL آن را ثبت کنید. این دکمه هیچ ارسال خارجی انجام نمی‌دهد.</p><label>URL واقعی پست (HTTPS)<input name="published_url" type="url" required dir="ltr" placeholder="https://..."></label><div class="form-actions"><button type="button" class="btn ghost" data-close-modal>انصراف</button><button class="btn primary" type="submit">تأیید و ثبت</button></div></form>`); $('#mark-published-form')?.addEventListener('submit', async event => { event.preventDefault(); try { await api(`/api/publish/${encodeURIComponent(id)}/manual-published`, { method: 'POST', body: { ...formData(event.target), confirm: true } }); closeModal(); toast('انتشار دستی ثبت شد', 'success'); await renderRoute(); } catch (e) { showError(e); } }); };
  return page(html, () => {
    $$('[data-publish-retry]').forEach(b => b.addEventListener('click', async () => { if (!confirmExternal('تلاش مجدد انتشار انجام شود؟ اگر نتیجه قبلی نامشخص بود، ابتدا پلتفرم را بررسی کنید.')) return; try { await api(`/api/publish/${encodeURIComponent(b.dataset.publishRetry)}/retry`, { method: 'POST', body: {} }); toast('کار انتشار دوباره در صف قرار گرفت', 'success'); await renderRoute(); } catch (e) { showError(e); } }));
    $$('[data-mark-published]').forEach(b => b.addEventListener('click', () => mark(b.dataset.markPublished)));
    $$('[data-copy-package]').forEach(b => b.addEventListener('click', () => { const job = jobs.find(j => j.id === b.dataset.copyPackage); copy(parse(job.manual_package_json, {})?.caption || ''); }));
    $$('[data-download-package]').forEach(b => b.addEventListener('click', () => { const job = jobs.find(j => j.id === b.dataset.downloadPackage); downloadText(JSON.stringify(parse(job.manual_package_json, {}), null, 2), `nasra-${job.platform}-${job.id}.json`, 'application/json'); }));
    $$('[data-route-link]').forEach(b => b.addEventListener('click', () => navigate(b.dataset.routeLink)));
  });
}

async function integrationsPage() {
  const r = await api('/api/integrations'); const d = r.data; const configured = d.configured || {};
  const status = (key, label) => `<div class="status-row"><code>${label}</code>${configured[key] ? badge('configured', 'ok') : badge('not configured', 'warn')}</div>`;
  const html = `${intro('یکپارچه‌سازی‌ها و اعتبارنامه‌ها', 'Secrets فقط در Cloudflare Secrets هستند. این صفحه فقط حضور/عدم حضور و وضعیت را نشان می‌دهد، نه مقدار محرمانه.', '<button class="btn ghost" data-route-link="settings">تنظیم کانال‌ها</button>')}<div class="grid two"><div>${card('Secrets و binding', `<div class="status-grid">${Object.keys(configured).map(k => status(k, k)).join('')}</div><p class="small muted">در صورت نبود هر Secret، سرویس مربوط «not configured» می‌شود و بقیه سیستم و Manual Mode کار می‌کند.</p>`)}</div><div>${card('Instagram Graph API', `<div class="row">${badge(d.instagram?.token_status || 'not_configured', d.instagram?.token_status === 'active' ? 'ok' : 'warn')}${badge(d.instagram?.auth_mode || 'instagram', 'info')}</div><p class="small">نسخه API: <code>${escapeHtml(d.instagram?.api_version || 'v26.0')}</code><br>انقضای توکن: ${d.instagram?.token_expires_at ? formatJalali(d.instagram.token_expires_at) : 'نامشخص/ثبت نشده'}<br>آخرین تازه‌سازی: ${d.instagram?.last_refreshed_at ? formatJalali(d.instagram.last_refreshed_at) : '—'}<br>آخرین Pull موفق: ${d.instagram?.last_successful_pull?.at ? formatJalali(d.instagram.last_successful_pull.at) : '—'}</p>${d.instagram?.last_error ? `<div class="notice danger">${escapeHtml(d.instagram.last_error)}</div>` : ''}<div class="form-actions"><button class="btn subtle" data-test-platform="instagram">تست اتصال</button><button class="btn ghost" id="refresh-ig">تازه‌سازی توکن</button></div>`)}</div></div><div class="grid two" style="margin-top:16px"><div>${card('Webhook اینستاگرام', `<label>Callback URL<input readonly dir="ltr" value="${escapeHtml(d.instagram_webhooks?.url || '')}"></label><div class="form-actions"><button class="btn ghost small-btn" data-copy-value="${escapeHtml(d.instagram_webhooks?.url || '')}">کپی URL</button></div><p class="small">GET verification با IG_VERIFY_TOKEN و POST با X-Hub-Signature-256 و IG_APP_SECRET. رویدادها dedupe و در background پردازش می‌شوند.</p><a href="https://developers.facebook.com/documentation/instagram-platform/webhooks" target="_blank" rel="noopener" class="small">مستندات رسمی Webhooks</a>`)}</div><div>${card('Telegram و Rubika', `<p class="small">Telegram owner webhook:<br><code>${escapeHtml(d.telegram?.webhook_url || '')}</code></p><div class="form-actions"><button class="btn ghost small-btn" data-copy-value="${escapeHtml(d.telegram?.webhook_url || '')}">کپی Telegram URL</button><button class="btn primary small-btn" id="setup-telegram-webhook">ثبت Webhook از Worker</button><button class="btn subtle small-btn" data-test-platform="telegram">تست بات تلگرام</button><button class="btn subtle small-btn" data-test-platform="rubika">تست بات روبیکا</button></div><div class="notice ${d.rubika?.channel_id_present ? 'ok' : 'warn'}">Rubika channel: ${d.rubika?.channel_id_present ? 'configured' : 'not configured'}<br>آلبوم بومی: <strong>needs verification</strong>؛ بسته دستی جایگزین امن است.</div>`)}</div></div><div style="margin-top:16px">${card('مستندات مرجع و آماده‌سازی', `<div class="list"><div class="list-item"><strong>Meta Instagram Login / Facebook Login</strong><p class="small">هر دو مسیر توکن در راهنما مستند شده‌اند. مسیر پیش‌فرض را در Settings انتخاب کنید؛ حساب Business/Creator و permissionهای لازم برای App Review جدا هستند.</p><a href="https://developers.facebook.com/documentation/instagram-platform/instagram-graph-api" target="_blank" rel="noopener" class="small">Instagram Platform رسمی</a></div><div class="list-item"><strong>Rubika Bot API v3</strong><p class="small">فقط botapi.rubika.ir/v3 و متدهای رسمی؛ هیچ session-login یا scraping استفاده نمی‌شود.</p><a href="https://rubika.ir/botapi/methods" target="_blank" rel="noopener" class="small">rubika.ir/botapi/methods</a></div></div>`)}</div>`;
  return page(html, () => {
    $$('[data-copy-value]').forEach(b => b.addEventListener('click', () => copy(b.dataset.copyValue)));
    $('#setup-telegram-webhook')?.addEventListener('click', async () => { if (!window.confirm('Webhook تلگرام به همین Worker و با TG_SECRET ثبت شود؟')) return; try { await api('/api/integrations/telegram/webhook', { method: 'POST', body: {} }); toast('Webhook تلگرام ثبت شد', 'success'); } catch (e) { showError(e); } });
    $$('[data-test-platform]').forEach(b => b.addEventListener('click', async () => { b.disabled = true; try { const result = await api('/api/integrations/test', { method: 'POST', body: { platform: b.dataset.testPlatform } }); toast(`اتصال موفق: ${result.data.username || result.data.id || 'OK'}`, 'success'); } catch (e) { showError(e); } finally { b.disabled = false; } }));
    $('#refresh-ig')?.addEventListener('click', async () => { if (!window.confirm('تازه‌سازی توکن طبق مسیر رسمی انجام شود؟')) return; try { const result = await api('/api/integrations/refresh', { method: 'POST', body: {} }); toast(result.data.refreshed ? 'توکن تازه و رمزنگاری ذخیره شد' : `تازه‌سازی لازم نیست: ${result.data.reason || ''}`, 'success'); await renderRoute(); } catch (e) { showError(e); } });
    $$('[data-route-link]').forEach(b => b.addEventListener('click', () => navigate(b.dataset.routeLink)));
  });
}

async function settingsPage() {
  const [r, health] = await Promise.all([api('/api/settings'), api('/api/health')]); const d = r.data || {};
  const html = `${intro('تنظیمات و سلامت', 'تنظیمات غیرمحرمانه در D1 ذخیره می‌شوند. Secrets را هرگز در این فرم یا Playbook وارد نکنید.', '<button class="btn ghost" id="settings-health">بررسی سلامت</button>')}<div class="grid two"><div>${card('کانال‌ها، مسیر توکن و سهمیه', `<form id="settings-form" class="stack"><label>عنوان استودیو<input name="studio_title" value="${escapeHtml(d.studio_title || '')}"></label><label>Chat ID کانال تلگرام (غیرمحرمانه)<input name="tg_channel_id" dir="ltr" value="${escapeHtml(d.tg_channel_id || '')}" placeholder="@nasra_channel یا -100..."></label><label>Chat ID کانال روبیکا<input name="rubika_channel_id" dir="ltr" value="${escapeHtml(d.rubika_channel_id || '')}"></label><label>مسیر Instagram Login<select name="ig_auth_mode"><option value="instagram">Instagram Login — graph.instagram.com</option><option value="facebook">Facebook Login — graph.facebook.com</option><option value="auto">Auto (پیش‌فرض امن: Instagram)</option></select></label><label>نسخه Graph API<input name="ig_api_version" dir="ltr" value="${escapeHtml(d.ig_api_version || 'v26.0')}"></label><div class="form-grid"><label>سقف توکن روزانه کل<input name="global_daily_token_cap" type="number" value="${d.global_daily_token_cap || 150000}"></label><label>سقف درخواست روزانه کل<input name="global_daily_request_cap" type="number" value="${d.global_daily_request_cap || 250}"></label></div><div class="form-grid"><label>تعداد snapshotهای Sheets<input name="backup_keep_snapshots" type="number" min="1" max="60" value="${d.backup_keep_snapshots || 14}"></label><label>ساعت‌های پیش‌فرض (با ویرگول)<input name="posting_hours" dir="ltr" value="${(d.default_posting_hours || []).join(',')}"></label></div><label class="check-label"><input type="checkbox" name="carousel_strict_no_mixed" ${d.carousel_strict_no_mixed !== false ? 'checked' : ''}> قانون سخت‌گیرانه عدم ترکیب عکس/ویدیو در کروسل</label><label class="check-label"><input type="checkbox" name="r2_enabled" ${d.r2_enabled ? 'checked' : ''}> فعال‌سازی اختیاری R2 (نیازمند binding و ممکن است روش پرداخت بخواهد)</label><label>R2 public base URL (اختیاری)<input name="r2_public_base_url" dir="ltr" value="${escapeHtml(d.r2_public_base_url || '')}" placeholder="https://pub-....r2.dev"></label><div class="form-actions"><button class="btn primary" type="submit">ذخیره تنظیمات</button></div></form>`)}</div><div>${card('Health و قراردادهای امنیتی', `<div id="health-result"><div class="status-row"><span>Worker / D1</span>${health.ok ? badge('healthy', 'ok') : badge('error', 'danger')}</div><p class="small">زمان سرور: ${formatJalali(health.time)}<br>تاریخ جلالی سرور: ${faDigits(health.jalali?.date || '')}<br>نسخه: ${escapeHtml(health.version || '')}</p></div><div class="notice info">ورود با HMAC-signed HttpOnly cookie، CSRF، rate limit و CSP انجام می‌شود. Webhookهای Telegram/Instagram مسیر مستقل و احرازشده دارند.</div><div class="notice warn">برای استفاده واقعی، Secretهای OWNER_PASSWORD و SESSION_SECRET قوی بسازید. SESSION_SECRET کلید رمزنگاری توکن refresh‌شده نیز هست؛ آن را نچرخانید مگر اینکه توکن را دوباره وارد کنید.</div>`)}</div></div>`;
  return page(html, () => { const form = $('#settings-form'); form.ig_auth_mode.value = d.ig_auth_mode || 'instagram'; form.addEventListener('submit', async event => { event.preventDefault(); const data = formData(form); data.carousel_strict_no_mixed = form.carousel_strict_no_mixed.checked; data.r2_enabled = form.r2_enabled.checked; data.default_posting_hours = data.posting_hours.split(',').map(x => x.trim()).filter(Boolean); delete data.posting_hours; try { await api('/api/settings', { method: 'PUT', body: data }); toast('تنظیمات ذخیره شد', 'success'); } catch (e) { showError(e); } }); $('#settings-health')?.addEventListener('click', async () => { try { const h = await api('/api/health'); $('#health-result').innerHTML = `<div class="notice ok">سلامت بررسی شد: ${formatJalali(h.time)} · D1 ${h.db ? 'متصل' : 'قطع'}</div>`; } catch (e) { showError(e); } }); });
}

async function logsPage() {
  const r = await api('/api/logs'); const logs = r.data || [];
  const html = `${intro('لاگ و حسابرسی', 'هر تأیید، تغییر پرامپت، انتشار، خطا و بازیابی در Audit Log ثبت می‌شود. IP فقط به شکل hash و Secrets هرگز ثبت نمی‌شوند.', '<button class="btn ghost" id="logs-refresh">↻</button>')}${logs.length ? `<div class="table-wrap"><table><thead><tr><th>زمان</th><th>کننده</th><th>عمل</th><th>موجودیت</th><th>جزئیات امن</th></tr></thead><tbody>${logs.map(l => `<tr><td>${formatJalali(l.created_at)}</td><td>${escapeHtml(l.actor)}</td><td>${badge(l.action, l.action.includes('failed') || l.action.includes('error') ? 'danger' : 'info')}</td><td>${escapeHtml(l.entity_type)}<br><code>${escapeHtml(l.entity_id || '')}</code></td><td><pre style="max-width:360px;max-height:150px;margin:0">${pretty(parse(l.details_json, {}))}</pre></td></tr>`).join('')}</tbody></table></div>` : empty('لاگی وجود ندارد')}`;
  return page(html, () => $('#logs-refresh')?.addEventListener('click', renderRoute));
}

async function backupPage() {
  const r = await api('/api/backup'); const snapshots = r.data || []; const last = r.last;
  const html = `${intro('پشتیبان‌گیری و بازیابی', 'هر شب Worker به Apps Script می‌نویسد؛ تاریخ/ساعت/ID با فرمت TEXT (@) پیش از setValues حفظ می‌شوند. Mirrorها هیچ ردیفی را حذف نمی‌کنند.', '<button class="btn primary" id="backup-export">دانلود JSON کامل</button>')}<div class="grid two"><div>${card('Google Sheets / Apps Script', `<p class="small">آخرین وضعیت: ${last ? `${last.status} · ${formatJalali(last.at)} · ${number(last.rows)} ردیف` : 'هنوز پشتیبان موفق ثبت نشده است'}</p><div class="notice info">GAS_URL و GAS_KEY در Secrets قرار می‌گیرند. در Sheets، ستون‌های scheduled_jalali و created_at به‌صورت متن باقی می‌مانند؛ «21:00» و «1405/07/23» به عدد تبدیل نمی‌شوند.</div><div class="form-actions"><button class="btn primary" id="backup-run">اجرای پشتیبان‌گیری Sheets</button></div>`)}</div><div>${card('بازیابی از JSON', `<form id="restore-form" class="stack"><label>فایل پشتیبان JSON<input name="file" type="file" accept="application/json,.json" required></label><p class="help">Restore فقط upsert انجام می‌دهد و داده‌های موجود را حذف نمی‌کند. Secrets و Sessionها در فایل نیستند.</p><button class="btn warn" type="submit">بازیابی و upsert</button></form>`)}</div></div><div style="margin-top:16px">${card('Snapshotهای ثبت‌شده', snapshots.length ? `<div class="table-wrap"><table><thead><tr><th>زمان</th><th>مقصد</th><th>وضعیت</th><th>ردیف</th><th>خطا</th></tr></thead><tbody>${snapshots.map(s => `<tr><td>${formatJalali(s.created_at)}<br>${faDigits(s.jalali_date)} ${faDigits(s.tehran_time)}</td><td>${escapeHtml(s.destination)}</td><td>${statusBadge(s.status)}</td><td>${number(s.rows_exported)}</td><td>${escapeHtml(s.error_message || '—')}</td></tr>`).join('')}</tbody></table></div>` : empty('Snapshotی ثبت نشده است'))}</div>`;
  return page(html, () => { $('#backup-export')?.addEventListener('click', async () => { try { downloadBlob(await apiBlob('/api/backup/export'), `nasra-backup-${todayJalali().date.replaceAll('/', '-')}.json`); toast('فایل پشتیبان دانلود شد', 'success'); } catch (e) { showError(e); } }); $('#backup-run')?.addEventListener('click', async event => { event.target.disabled = true; try { await api('/api/backup/run', { method: 'POST', body: {} }); toast('پشتیبان Sheets انجام شد', 'success'); await renderRoute(); } catch (e) { showError(e); } finally { event.target.disabled = false; } }); $('#restore-form')?.addEventListener('submit', async event => { event.preventDefault(); const file = event.target.file.files[0]; if (!file) return; if (!window.confirm('بازیابی فایل انجام شود؟ داده‌های موجود حذف نمی‌شوند اما ردیف‌های هم‌کلید به‌روزرسانی می‌شوند.')) return; try { const data = JSON.parse(await file.text()); let cursor = null; let total = 0; let done = false; while (!done) { const result = await api('/api/backup/restore', { method: 'POST', body: { ...data, restore_cursor: cursor } }); total += Number(result.data.restored || 0); done = result.data.done === true; cursor = result.data.next_cursor; if (!done && !cursor) throw new Error('اشکال در ادامه بازیابی'); } toast(`${number(total)} ردیف بازیابی شد`, 'success'); } catch (e) { showError(e); } }); });
}

async function selftestPage() {
  const html = `${intro('آزمون پذیرش سرتاسری', 'تست‌ها با ID جدا و بدون شبکه خارجی اجرا می‌شوند؛ برای رعایت سقف ۵۰ کوئری D1 در هر invocation، UI پنج بخش را پشت‌سرهم اجرا می‌کند.', '<button class="btn primary" id="run-selftest">اجرای همه تست‌ها</button>')}<div id="selftest-result">${notice('برای شروع روی «اجرای همه تست‌ها» بزنید. خروجی باید ۱۶/۱۶ سبز باشد؛ تست‌ها هیچ پست یا پیام واقعی ارسال نمی‌کنند.', 'info')}</div>`;
  return page(html, () => $('#run-selftest')?.addEventListener('click', async event => {
    event.target.disabled = true;
    const output = $('#selftest-result');
    try {
      const tests = []; let passed = 0; let checkedAt = '';
      for (const part of ['p1', 'p2', 'p3', 'p4', 'p5']) {
        output.innerHTML = `<div class="empty">در حال اجرای بخش ${faDigits(part.slice(1))} از ۴…</div>`;
        const result = await api(`/api/selftest?part=${part}`);
        tests.push(...result.tests); passed += result.passed; checkedAt = result.checked_at;
      }
      const ok = passed === tests.length;
      output.innerHTML = `<div class="notice ${ok ? 'ok' : 'danger'}"><strong>${ok ? 'همه تست‌ها قبول شدند' : 'برخی تست‌ها قبول نشدند'}: ${faDigits(passed)} / ${faDigits(tests.length)}</strong><br>شبکه خارجی: ندارد · پنج invocation کوچک · زمان: ${formatJalali(checkedAt)}</div><div class="table-wrap" style="margin-top:15px"><table><thead><tr><th>نتیجه</th><th>تست پذیرش</th><th>جزئیات</th></tr></thead><tbody>${tests.map(t => `<tr><td>${t.ok ? badge('PASS', 'ok') : badge('FAIL', 'danger')}</td><td>${escapeHtml(t.name)}</td><td><pre style="max-width:420px;max-height:130px;margin:0">${pretty(t.details)}</pre></td></tr>`).join('')}</tbody></table></div>`;
    } catch (e) { output.innerHTML = `<div class="notice danger">${escapeHtml(errorText(e))}</div>`; }
    finally { event.target.disabled = false; }
  }));
}

export async function renderPageRoute(route) {
  if (route.name === 'dashboard') return dashboardPage();
  if (route.name === 'approvals') return approvalsPage();
  if (route.name === 'pipeline') return pipelinePage();
  if (route.name === 'content' && route.id) return contentPage(route.id);
  if (route.name === 'calendar') return calendarPage();
  if (route.name === 'sources') return sourcesPage();
  if (route.name === 'playbook') return playbookPage();
  if (route.name === 'agents') return agentsPage();
  if (route.name === 'inbox') return inboxPage();
  if (route.name === 'analytics') return analyticsPage();
  if (route.name === 'publish') return publishPage();
  if (route.name === 'integrations') return integrationsPage();
  if (route.name === 'settings') return settingsPage();
  if (route.name === 'logs') return logsPage();
  if (route.name === 'backup') return backupPage();
  if (route.name === 'selftest') return selftestPage();
  return dashboardPage();
}
